command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/current-main-packaging-20261005"
$candidate="d5d112d727b8b07eb3070efe048d27f0ffb8a8ca"
$baseline="a84ff56597ca638b31fdcb4a5b0bc1356cb443f3"
$acceptedPayload="00f90c30800fb66f88184211442f6eeb05a950b7"
$temp=Join-Path $env:RUNNER_TEMP ("package-docs-final-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before docs validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before docs validation: $branchSha"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & git diff --quiet $acceptedPayload $candidate -- packaging/licenses
  if($LASTEXITCODE -ne 0){throw "accepted packaged license/provenance payload changed after run #435"}

  & cmd /c test.bat policy
  if($LASTEXITCODE -ne 0){throw "policy validation failed"}

  & python -X utf8 -m unittest tests.winui.test_release_payload_contract tests.winui.test_installer_contract
  if($LASTEXITCODE -ne 0){throw "package contract tests failed"}

  $status=Get-Content -Raw -Encoding UTF8 -LiteralPath "docs\development\CURRENT_STATUS.md"
  $dist=Get-Content -Raw -Encoding UTF8 -LiteralPath "docs\development\DISTRIBUTION_LICENSE_REVIEW.md"
  $pack=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\README.md"
  foreach($body in @($status,$dist,$pack)){
    if(-not $body.Contains("37306799266")){throw "current #435 package evidence missing"}
    if(-not $body.Contains("40f0f12797c6731f823dd3e438b09fc575a78a54f9962c14fb572e5d70dfdcc5")){throw "current package manifest digest missing"}
  }
  Write-Host "CURRENT_PACKAGE_DOCS_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
